import goLinks from "./go.json" with { type: "json" };
import oldUrls from "./oldurls.json" with { type: "json" };

const redirects: Record<string, string> = {
  ...oldUrls,
  ...Object.fromEntries(
    Object.entries(goLinks).map(([name, url]) => [`/go/${name}/`, url]),
  ),
};

// The API reference isn't built yet (it comes back generated by `ende doc`),
// so redirects into it would point at missing pages.
for (const [from, to] of Object.entries(redirects)) {
  if (to.startsWith("/api/")) {
    delete redirects[from];
  }
}

export default {
  location: "https://docs.ende.sh",
  search: true,
  ignore: [
    "AGENTS.md",
    "LICENSE",
    "README.md",
    "ende.json",
    "ende.lock",
    "go.json",
    "oldurls.json",
  ],
  copy: { static: "/", "examples/scripts": "/examples/scripts/" },
  redirects,
};
